test('Upload de arquivo CSV', async ({ page }) => {
  await page.goto('https://app.exemplo.com/importar')

  // Definir o arquivo para upload (usar path local)
  const [fileChooser] = await Promise.all([
    page.waitForEvent('filechooser'),
    page.click('[data-testid="btn-selecionar-arquivo"]')
  ])
  await fileChooser.setFiles('./fixtures/dados-teste.csv')

  // Verificar preview
  await expect(page.locator('.preview-linhas')).toContainText('10 linhas
encontradas')

  // Confirmar importação
  await page.click('[data-testid="btn-importar"]')
  await expect(page.locator('.resultado')).toContainText('Importação concluída')
})

