// pages/LoginPage.js
class LoginPage {
  constructor(page) {
    this.page = page
    this.emailField = page.locator('#email')
    this.passwordField = page.locator('#password')
    this.submitButton = page.locator('#btn-submit')
  }

  async login(email, senha) {
    await this.emailField.fill(email)
    await this.passwordField.fill(senha)
    await this.submitButton.click()
  }
}

// tests/login.spec.js
test('login com credenciais válidas', async ({ page }) => {
  const loginPage = new LoginPage(page)
  await loginPage.login('user@qa.com', 'Senha@123')
  // O teste não sabe como o login funciona — só que ele deve funcionar
})
• Benefício real: quando o ID do botão mudar de #btn-submit para #btn-entrar, você muda em
1 arquivo — não em 50 testes.
Flaky Tests — O Inimigo Silencioso
Flaky test é um teste que às vezes passa, às vezes falha — sem mudança no código. É pior que um
teste que sempre falha, porque destrói a confiança do time na suite inteira.
