// tests/performance/carga.js
import http from 'k6/http'
import { check, sleep } from 'k6'

export const options = {
  stages: [
    { duration: '30s', target: 10 }, // ramp up: 0 -> 10 usuários
    { duration: '1m', target: 50 }, // sustain: 50 usuários por 1 min
    { duration: '30s', target: 0 }, // ramp down: 50 -> 0
  ],
  thresholds: {
    http_req_duration: ['p(95)<500'], // 95% das req < 500ms
    http_req_failed: ['rate<0.01'], // menos de 1% de erros
  },
}

export default function () {
  const response = http.get('https://api.sistema.com/v1/produtos')

  check(response, {
    'status 200': (r) => r.status === 200,
    'tempo < 500ms': (r) => r.timings.duration < 500,
    'body não vazio': (r) => r.body.length > 0,
  })

  sleep(1)
}

