#041
Criar Page Object para a página de Login
Pleno
• Encapsule seletores e ações — o teste não deve saber como a página funciona
// pages/LoginPage.js
class LoginPage {
  constructor(page) {
    this.page = page
    this.campoUsuario = page.locator('#username')
    this.campoSenha = page.locator('#password')
    this.btnSubmit = page.locator('button[type="submit"]')
    this.mensagem = page.locator('#flash')
  }
  async navegar() { await this.page.goto('/login') }
  async login(user, pass) {
    await this.campoUsuario.fill(user)
    await this.campoSenha.fill(pass)
    await this.btnSubmit.click()
  }
  async getMensagem() { return this.mensagem.textContent() }
}
module.exports = { LoginPage }

