Verificar que página lida com parâmetros de URL maliciosos
Pleno
• XSS via URL é um dos vetores mais comuns
test('parâmetros maliciosos na URL não quebram a página', async ({ page }) => {
  const payloads = [
    '?id=<script>alert(1)</script>',
    '?search=%27%20OR%20%271%27%3D%271', // SQL injection encoded
    '?redirect=javascript:alert(1)',
  ]

  for (const payload of payloads) {
    const res = await page.goto(`https://the-internet.herokuapp.com/${payload}`)
    // Não deve causar erro 500
    expect(res?.status()).not.toBe(500)
    // Não deve executar alert — verificar que página carregou normalmente
    await expect(page.locator('body')).toBeVisible()
  }
})

