#084
Criar teste de contrato de API com schema JSON
Sênior
• Valide estrutura da resposta, não só o conteúdo
// npm install ajv
import Ajv from 'ajv'

const schemaUsuario = {
  type: 'object',
  required: ['id', 'nome', 'email', 'ativo'],
  properties: {
    id: { type: 'integer' },
    nome: { type: 'string', minLength: 2 },
    email: { type: 'string', format: 'email' },
    ativo: { type: 'boolean' }
  }
}

test('contrato GET /usuario/:id', async ({ request }) => {
  const res = await request.get('/api/usuarios/1')
  const body = await res.json()
  const ajv = new Ajv()
  const valid = ajv.validate(schemaUsuario, body)
  expect(valid, ajv.errorsText()).toBe(true)
})

