#088
Medir e validar performance de carregamento de página
Sênior
• Use window.performance.timing via evaluate()
test('performance de carregamento', async ({ page }) => {
  await page.goto('/dashboard')
  const timing = await page.evaluate(() => {
    const t = window.performance.timing
    return {
      ttfb: t.responseStart - t.requestStart,
      domLoaded: t.domContentLoadedEventEnd - t.navigationStart,
      totalLoad: t.loadEventEnd - t.navigationStart
    }
  })
  console.log('TTFB:', timing.ttfb, 'ms')
  expect(timing.domLoaded).toBeLessThan(3000) // < 3s
  expect(timing.totalLoad).toBeLessThan(5000) // < 5s
})

