#092
Validar conteúdo de PDF gerado pela aplicação
Sênior
• Use pdf-parse para extrair e verificar texto do PDF
// npm install pdf-parse
import pdfParse from 'pdf-parse'
import * as fs from 'fs'

test('PDF de contrato contém dados corretos', async ({ page }) => {
  await page.goto('/contratos/123')
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.click('#btn-baixar-contrato')
  ])
  await download.saveAs('./temp/contrato.pdf')
  const dataBuffer = fs.readFileSync('./temp/contrato.pdf')
  const pdfData = await pdfParse(dataBuffer)
  expect(pdfData.text).toContain('CONTRATO DE PRESTAÇÃO')
  expect(pdfData.text).toContain('CPF: 123.456.789-00')
})

