#093
Criar relatório customizado com métricas de QA
Sênior
• Publique métricas além do pass/fail: tempo, cobertura, flakyness
// reporters/metricas-reporter.js
class MetricasReporter {
  onBegin(config, suite) {
    this.inicio = Date.now()
    this.total = suite.allTests().length
  }
  onTestEnd(test, result) {
    if (result.status === 'failed') this.falhas++
    if (result.status === 'flaky') this.flaky++
  }
  onEnd(result) {
    const duracao = (Date.now() - this.inicio) / 1000
    console.log(`Total: ${this.total} | Falhas: ${this.falhas} | Flaky:
${this.flaky} | Tempo: ${duracao}s`)
  }
}
#094
Testar fluxo de renovação de token JWT expirado
Sênior
• Simule expiração e verifique refresh automático
test('renovação automática de token', async ({ page, context }) => {
