#095
Implementar teste de resiliência — simular falha de serviço externo
Sênior
• Use page.route para simular timeout ou erro de API
test('sistema trata falha do serviço de CEP', async ({ page }) => {
  // Simular timeout no serviço de CEP
  await page.route('**/api.cep.la/**', async route => {
    await route.abort('timedout')
  })
  await page.goto('/endereco')
  await page.fill('#cep', '30112-000')
  await page.locator('#cep').blur()
  // Verificar que sistema exibe mensagem amigável, não erro técnico
  await expect(page.locator('.aviso-cep')).toContainText('não foi possível
consultar')
  // Verificar que formulário ainda pode ser preenchido manualmente
  await expect(page.locator('#rua')).toBeEditable()
})
