text:
#099
Implementar teste de acessibilidade com relatório detalhado
Sênior
• WCAG 2.1 AA — obrigatório em sistemas governamentais e financeiros
// npm install @axe-core/playwright
import AxeBuilder from '@axe-core/playwright'

test('acessibilidade WCAG 2.1 AA — checkout', async ({ page }) => {
  await page.goto('/checkout')
  const resultado = await new AxeBuilder({ page })
    .withTags(['wcag2a', 'wcag2aa', 'wcag21aa'])
    .exclude('.cookie-banner') // excluir componente terceiro
    .analyze()

  const criticos = resultado.violations.filter(v => v.impact === 'critical')
  if (criticos.length > 0) {
    console.log('Violações críticas:', JSON.stringify(criticos, null, 2))
  }
  expect(criticos.length).toBe(0) // zero tolerância para críticos
})

