    { url: '/api/auth/status', esperado: 200 },
    { url: '/api/produtos', esperado: 200 },
  ]
  for (const ep of endpoints) {
    const res = await request.get(process.env.BASE_URL + ep.url)
    expect(res.status(), `${ep.url} retornou ${res.status()}`).toBe(ep.esperado)
  }
})

