#022
Testar rate limiting — muitas requisições retornam 429
Pleno
• Verificar que a API tem proteção contra abuso
test('rate limiting', async ({ request }) => {
  const requisicoes = Array.from({ length: 50 }, () =>
    request.get('https://reqres.in/api/users')
  )
  const respostas = await Promise.all(requisicoes)
  const status = respostas.map(r => r.status())
  const comRateLimit = status.filter(s => s === 429)
  console.log(`429s recebidos: ${comRateLimit.length} de 50`)
  // Se a API tem rate limiting, pelo menos alguns devem ser 429
})

