#023
Validar contrato com JSON Schema (Ajv)
Pleno
• Schema validation é teste de contrato — não apenas de conteúdo
import Ajv from 'ajv'
import addFormats from 'ajv-formats'

const schema = {
  type: 'object',
  required: ['data'],
  properties: {
    data: {
      type: 'object',
      required: ['id', 'email', 'first_name', 'last_name'],
      properties: {
        id: { type: 'integer', minimum: 1 },
        email: { type: 'string', format: 'email' },
        first_name: { type: 'string', minLength: 1 },
        last_name: { type: 'string', minLength: 1 },
      }
    }
  }
}

test('schema validation GET /users/:id', async ({ request }) => {
  const res = await request.get('https://reqres.in/api/users/2')
  const body = await res.json()
  const ajv = new Ajv()
  addFormats(ajv)
  const valid = ajv.validate(schema, body)
  expect(valid, ajv.errorsText()).toBe(true)
})

