#027
Testar campos com injeção SQL nos parâmetros
Pleno
• Segurança básica — API não deve vazar dados nem crashar
const payloads_sql = [
  "' OR '1'='1",
  "'; DROP TABLE usuarios; --",
  "1 UNION SELECT * FROM usuarios--",
  "admin'--",
]

for (const payload of payloads_sql) {
  test(`SQL injection: ${payload.substring(0, 20)}`, async ({ request }) => {
    const res = await request.get(`/api/usuarios?q=${encodeURIComponent(payload)}`)
    // Não deve retornar 500 (erro interno)
    expect(res.status()).not.toBe(500)
    // Não deve retornar mais dados do que o esperado
    if (res.status() === 200) {
      const body = await res.json()
      expect(body.data.length).toBeLessThanOrEqual(100)
    }
  })
}

