  // Todas devem retornar 200
  expect(req1.status()).toBe(200)
  expect(req2.status()).toBe(200)
  expect(req3.status()).toBe(200)
  // Estado final deve ser o mesmo
  const b1 = await req1.json()
  const b3 = await req3.json()
  expect(b1.name).toBe(b3.name)
})
#030
Testar concorrência — 2 requisições simultâneas para o mesmo recurso
Pleno
• Race conditions são bugs difíceis de reproduzir
test('concorrência — sem race condition em cadastro', async ({ request }) => {
  const dados = { email: `concurrent_${Date.now()}@qa.test`, senha: 'Senha@123' }
  // Enviar 2 requisições simultâneas com mesmo email
  const [res1, res2] = await Promise.all([
    request.post('/api/usuarios', { data: dados }),
    request.post('/api/usuarios', { data: dados }),
  ])
  const statuses = [res1.status(), res2.status()].sort()
  // Uma deve criar (201) e outra deve falhar por duplicata (409)
  expect(statuses).toEqual([201, 409])
})

