#034
Testar header de cache — ETag e Cache-Control
Pleno
• Cache mal configurado = dados desatualizados para o usuário
test('recursos estáticos têm cache adequado', async ({ request }) => {
  const res1 = await request.get('/api/produtos/categorias')
  const etag = res1.headers()['etag']
  const cacheControl = res1.headers()['cache-control']

  // Deve ter estratégia de cache definida
  expect(cacheControl).toBeDefined()
  console.log('Cache-Control:', cacheControl)

  if (etag) {
    // Segunda requisição com ETag deve retornar 304
    const res2 = await request.get('/api/produtos/categorias', {
      headers: { 'If-None-Match': etag }
    })
    expect(res2.status()).toBe(304) // Not Modified
  }
})

