#035
Testar CORS — origens permitidas e bloqueadas
Pleno
• CORS mal configurado = vulnerabilidade de segurança
test('CORS permite origens autorizadas', async ({ request }) => {
  // Origem permitida
  const resPermitida = await request.get('/api/usuarios', {
    headers: { 'Origin': 'https://app.meusistema.com' }
  })
  const corspermitido = resPermitida.headers()['access-control-allow-origin']
  expect(['https://app.meusistema.com', '*']).toContain(corspermitido)

  // Origem bloqueada (se CORS for restrito)
  const resBloqueada = await request.get('/api/usuarios', {
    headers: { 'Origin': 'https://site-malicioso.com' }
  })
  const corsBloqueado = resBloqueada.headers()['access-control-allow-origin']
  expect(corsBloqueado).not.toBe('https://site-malicioso.com')
})

