#036
Testar Content Negotiation — JSON vs XML
Pleno
• API que suporta múltiplos formatos deve respeitar Accept header
test('Content Negotiation via Accept header', async ({ request }) => {
  // Solicitar JSON
  const resJson = await request.get('/api/usuarios/1', {
    headers: { 'Accept': 'application/json' }
  })
  expect(resJson.headers()['content-type']).toContain('application/json')

  // Solicitar XML (se suportado)
  const resXml = await request.get('/api/usuarios/1', {
    headers: { 'Accept': 'application/xml' }
  })
  // Deve responder 200 com XML ou 406 Not Acceptable
  expect([200, 406]).toContain(resXml.status())
  if (resXml.status() === 200) {
    expect(resXml.headers()['content-type']).toContain('xml')
  }
})

