#038
Verificar que soft delete não remove do banco mas esconde da API
Pleno
• Soft delete é contrato de API — recurso deletado não aparece em GET
test('recurso soft-deletado não aparece na listagem', async ({ request }) => {
  const headers = { Authorization: `Bearer ${process.env.TOKEN}` }

  // Criar e deletar
  const criar = await request.post('/api/tags', {
    data: { nome: `tag-delete-test-${Date.now()}` }, headers
  })
  const { id } = await criar.json()

  await request.delete(`/api/tags/${id}`, { headers })

  // Não deve aparecer na listagem
  const lista = await request.get('/api/tags', { headers })
  const body = await lista.json()
  const ids = body.data.map((t: any) => t.id)
  expect(ids).not.toContain(id)

  // GET direto deve retornar 404 ou 410
  const direto = await request.get(`/api/tags/${id}`, { headers })
  expect([404, 410]).toContain(direto.status())
})

