#040
Testar webhook — endpoint que recebe eventos externos
Pleno
• Webhooks têm assinatura HMAC — valide a segurança
import crypto from 'crypto'

test('webhook com assinatura HMAC válida é aceito', async ({ request }) => {
  const payload = JSON.stringify({
    evento: 'pagamento.aprovado',
    pedido_id: 12345,
    valor: 199.90
  })

  // Gerar assinatura HMAC-SHA256
  const assinatura = crypto
    .createHmac('sha256', process.env.WEBHOOK_SECRET!)
    .update(payload)
    .digest('hex')

  const res = await request.post('/api/webhooks/pagamento', {
    data: payload,
    headers: {
      'Content-Type': 'application/json',
      'X-Signature': `sha256=${assinatura}`
    }
  })
  expect(res.status()).toBe(200)
})

