#042
Testar endpoint de exportação assíncrona com polling
Pleno
• Exports grandes são assíncronos — poll até concluir
test('exportação assíncrona — poll até concluir', async ({ request }) => {
  const headers = { Authorization: `Bearer ${process.env.TOKEN}` }

  // Iniciar exportação
  const iniciar = await request.post('/api/exportacoes', {
    data: { tipo: 'clientes', formato: 'xlsx' }, headers
  })
  expect(iniciar.status()).toBe(202) // Accepted
  const { job_id } = await iniciar.json()

  // Poll até concluir (máx 30s)
  let status = 'PROCESSANDO'
  const inicio = Date.now()
  while (status === 'PROCESSANDO' && Date.now() - inicio < 30_000) {
    await new Promise(r => setTimeout(r, 1000))
    const poll = await request.get(`/api/exportacoes/${job_id}`, { headers })
    status = (await poll.json()).status
  }

  expect(status).toBe('CONCLUIDO')

  // Baixar o arquivo
  const download = await request.get(`/api/exportacoes/${job_id}/arquivo`, {
headers })
  expect(download.status()).toBe(200)
  expect(download.headers()['content-type']).toContain('spreadsheet')
})

