#047
Testar rate limiting com header Retry-After
Pleno
• Quando 429, API deve informar quando tentar de novo
test('429 inclui header Retry-After', async ({ request }) => {
  let ultimaResposta: any

  // Fazer requisições até atingir o limite
  for (let i = 0; i < 100; i++) {
    ultimaResposta = await request.get('/api/usuarios')
    if (ultimaResposta.status() === 429) break
  }

  if (ultimaResposta?.status() === 429) {
    const retryAfter = ultimaResposta.headers()['retry-after']
    expect(retryAfter).toBeDefined()
    const segundos = parseInt(retryAfter)
    expect(segundos).toBeGreaterThan(0)
    console.log(`Rate limited. Retry em ${segundos}s`)
  }
})

