test('SSRF — campo de URL não acessa rede interna', async ({ request }) => {
  const payloads_ssrf = [
    'http://localhost/admin',
    'http://127.0.0.1:6379', // Redis
    'http://169.254.169.254/', // AWS metadata
    'http://10.0.0.1/', // rede interna
  ]

  for (const url of payloads_ssrf) {
    const res = await request.post('/api/importar-url', {
      data: { url },
      headers: { Authorization: `Bearer ${process.env.TOKEN}` }
    })
    // Deve bloquear — nunca retornar 200 com conteúdo interno
    expect([400, 403, 422]).toContain(res.status())
    const body = await res.json()
    expect(body.error).toBeDefined()
  }
})

