#052
Testar endpoint de refresh token
Pleno
• JWT expira — o refresh não pode falhar
test('refresh token gera novo access token', async ({ request }) => {
  // Fazer login para obter tokens
  const login = await request.post('/api/auth/login', {
    data: { email: process.env.TEST_USER, senha: process.env.TEST_PASS }
  })
  const { access_token, refresh_token } = await login.json()

  // Usar refresh token
  const refresh = await request.post('/api/auth/refresh', {
    data: { refresh_token }
  })
  expect(refresh.status()).toBe(200)
  const { access_token: novo_token } = await refresh.json()

  // Novo token deve ser diferente do original
  expect(novo_token).not.toBe(access_token)

  // Novo token deve ser válido
  const teste = await request.get('/api/me', {
    headers: { Authorization: `Bearer ${novo_token}` }
  })
  expect(teste.status()).toBe(200)
})

