import WebSocket from 'ws'

test('WebSocket — receber evento em tempo real', async () => {
  await new Promise<void>((resolve, reject) => {
    const ws = new WebSocket(`${process.env.WS_URL}/eventos`, {
      headers: { Authorization: `Bearer ${process.env.TOKEN}` }
    })

    const timeout = setTimeout(() => {
      ws.close()
      reject(new Error('Timeout — nenhum evento recebido em 5s'))
    }, 5000)

    ws.on('open', () => {
      ws.send(JSON.stringify({ tipo: 'subscribe', canal: 'pedidos' }))
    })

    ws.on('message', (data) => {
      const msg = JSON.parse(data.toString())
      expect(msg.tipo).toBeDefined()
      clearTimeout(timeout)
      ws.close()
      resolve()
    })

    ws.on('error', reject)
  })
})

