  const res2 = await request.post('/api/pagamentos', { data: dados, headers })
  expect(res2.status()).toBe(200) // 200 = retornando resultado existente
  const body2 = await res2.json()

  // IDs devem ser iguais — não criou duplicata
  expect(body2.id).toBe(body1.id)
})

