#031
Testar fluxo OAuth2 Authorization Code completo
Sênior
• OAuth2 tem múltiplos passos — cada um deve ser validado
test('OAuth2 Authorization Code Flow', async ({ request }) => {
  // Passo 1: obter authorization code
  const authRes = await request.get('/oauth/authorize', {
    params: {
      client_id: process.env.CLIENT_ID,
      redirect_uri: 'https://app.qa.local/callback',
      response_type: 'code',
      scope: 'read:profile'
    }
  })
  const code = new URL(authRes.headers()['location']).searchParams.get('code')

  // Passo 2: trocar code por access_token
  const tokenRes = await request.post('/oauth/token', {
    form: {
      grant_type: 'authorization_code',
      code,
      client_id: process.env.CLIENT_ID,
      client_secret: process.env.CLIENT_SECRET,
      redirect_uri: 'https://app.qa.local/callback'
    }
  })
  expect(tokenRes.status()).toBe(200)
  const { access_token, token_type, expires_in } = await tokenRes.json()
  expect(access_token).toBeDefined()
  expect(token_type).toBe('Bearer')
  expect(expires_in).toBeGreaterThan(0)
})

