Sênior
• Qualidade não é só funcional — performance é requisito
const endpointsCriticos = [
  { path: '/api/auth/token', sla: 300 },
  { path: '/api/usuarios/perfil', sla: 500 },
  { path: '/api/produtos?limite=10', sla: 800 },
