  { path: '/api/relatorios/resumo', sla: 3000 },
]

for (const { path, sla } of endpointsCriticos) {
  test(`SLA ${path} < ${sla}ms`, async ({ request }) => {
    const amostras = []
    for (let i = 0; i < 5; i++) {
      const t0 = Date.now()
      await request.get(process.env.BASE_URL + path, {
        headers: { Authorization: `Bearer ${process.env.TOKEN}` }
      })
      amostras.push(Date.now() - t0)
