    const p95 = amostras.sort((a,b) => a-b)[Math.floor(amostras.length * 0.95)]
    console.log(`P95 de ${path}: ${p95}ms (SLA: ${sla}ms)`)
    expect(p95).toBeLessThanOrEqual(sla)
  })
}

