• Circuit breaker: após N falhas, para de tentar por um tempo
test('circuit breaker abre após falhas consecutivas', async ({ request }) => {
  const headers = { Authorization: `Bearer ${process.env.TOKEN}` }
  const statuses: number[] = []

  // Fazer requisições para serviço instável
  for (let i = 0; i < 20; i++) {
    const res = await request.get('/api/servico-externo/status', { headers })
    statuses.push(res.status())
    await new Promise(r => setTimeout(r, 200))
  }

  // Verificar que circuit breaker abriu (503 Service Unavailable)
  // Quando aberto, retorna 503 imediatamente sem tentar o downstream
  const circuitAberto = statuses.filter(s => s === 503).length
  console.log(`503s recebidos (circuit open): ${circuitAberto}/20`)
  console.log('Sequência de status:', statuses.join(', '))
})

