#035
Testar timeout e retry com backoff exponencial
Sênior
• Retry sem backoff causa thundering herd — sempre use backoff
import axiosRetry from 'axios-retry'
import axios from 'axios'

test('retry com backoff exponencial', async () => {
  const client = axios.create({ baseURL: process.env.API_URL })
  axiosRetry(client, {
    retries: 3,
    retryDelay: axiosRetry.exponentialDelay, // 1s, 2s, 4s
    retryCondition: (err) => {
      return axiosRetry.isNetworkOrIdempotentRequestError(err) ||
             err.response?.status === 503
    }
  })

  const inicio = Date.now()
  try {
    const res = await client.get('/api/servico-instavel',
      { headers: { Authorization: `Bearer ${process.env.TOKEN}` } }
    )
    console.log('Sucesso após retry. Tempo total:', Date.now() - inicio, 'ms')
  } catch (e) {
    const tempo = Date.now() - inicio
    // Com backoff 1+2+4 = 7s, tempo total deve refletir isso
    expect(tempo).toBeGreaterThan(6000)
    console.log('Falhou após retries. Tempo:', tempo, 'ms')
  }
})

