Sênior
• Bulk delete tem regras específicas: IDs inválidos, parcial vs total
test('DELETE /bulk — deletar múltiplos IDs', async ({ request }) => {
  const headers = { Authorization: `Bearer ${process.env.TOKEN_ADMIN}` }

  // Criar registros para deletar
  const ids: number[] = []
  for (let i = 0; i < 3; i++) {
    const r = await request.post('/api/tags', {
      data: { nome: `bulk-del-${Date.now()}-${i}` }, headers
    })
    ids.push((await r.json()).id)
  }

  // Deletar em bulk
  const del = await request.delete('/api/tags/bulk', {
    data: { ids }, headers
  })
  expect(del.status()).toBe(200)
