Testar ordenação estável em listagens paginadas
Sênior
• Paginação com ordenação inconsistente duplica e perde registros
test('ordenação estável entre páginas', async ({ request }) => {
  const headers = { Authorization: `Bearer ${process.env.TOKEN}` }
  const todosIds: number[] = []

  // Coletar todos os IDs paginando
  for (let pagina = 1; pagina <= 5; pagina++) {
    const res = await
request.get(`/api/produtos?pagina=${pagina}&limite=10&ordem=id_asc`, { headers })
    const body = await res.json()
    const ids = body.data.map((p: any) => p.id)
    todosIds.push(...ids)
    if (!body.has_next) break
  }

  // Sem duplicatas entre páginas
  const unicos = new Set(todosIds)
  expect(unicos.size).toBe(todosIds.length)

  // IDs devem estar em ordem crescente
  for (let i = 1; i < todosIds.length; i++) {
    expect(todosIds[i]).toBeGreaterThan(todosIds[i-1])
  }
})

