#044
Criar helper de autenticação reutilizável para toda a suite
Sênior
• DRY no setup de autenticação — toda a suite usa o mesmo helper
// helpers/auth.helper.ts
export class AuthHelper {
  private static tokenCache: Map<string, { token: string; expiry: number }> = new
Map()

  static async getToken(request: any, perfil: 'admin' | 'usuario' | 'financeiro') {
    const cached = this.tokenCache.get(perfil)
    if (cached && cached.expiry > Date.now()) return cached.token

    const credenciais = {
      admin: { email: process.env.ADMIN_EMAIL, senha: process.env.ADMIN_PASS },
      usuario: { email: process.env.USER_EMAIL, senha: process.env.USER_PASS },
      financeiro: { email: process.env.FIN_EMAIL, senha: process.env.FIN_PASS },
    }

    const res = await request.post('/api/auth/login', { data: credenciais[perfil]
})
    const { access_token, expires_in } = await res.json()

    this.tokenCache.set(perfil, {
      token: access_token,
      expiry: Date.now() + (expires_in - 60) * 1000 // renovar 1min antes
    })
    return access_token
  }
}

