#045
Testar proteção contra enumeração de usuários
Sênior
• Timing attack: não revelar se email existe via tempo de resposta
test('tempo de resposta igual para email existente e inexistente', async ({ request
}) => {
  const amostras = { existente: [] as number[], inexistente: [] as number[] }

  for (let i = 0; i < 10; i++) {
    let t = Date.now()
    await request.post('/api/auth/login', {
      data: { email: 'existente@email.com', senha: 'senha_errada' }
    })
    amostras.existente.push(Date.now() - t)

    t = Date.now()
    await request.post('/api/auth/login', {
      data: { email: `inexistente_${i}@naoexiste.com`, senha: 'senha_errada' }
    })
    amostras.inexistente.push(Date.now() - t)
  }

  const mediaExistente = amostras.existente.reduce((a, b) => a + b) / 10
  const mediaInexistente = amostras.inexistente.reduce((a, b) => a + b) / 10
  const diferenca = Math.abs(mediaExistente - mediaInexistente)

  console.log(`Tempo médio existente: ${mediaExistente.toFixed(0)}ms, inexistente:
${mediaInexistente.toFixed(0)}ms`)
  // Diferença > 200ms indica timing attack possível
  expect(diferenca).toBeLessThan(200)
})

