Sênior
• Throttling por IP protege contra DDoS e ataques de força bruta
test('throttling por IP — login bloqueado após muitas tentativas', async ({ request
}) => {
  const tentativas = 20
  const respostas: number[] = []

  for (let i = 0; i < tentativas; i++) {
    const res = await request.post('/api/auth/login', {
      data: { email: 'alvo@email.com', senha: `tentativa_${i}` }
    })
    respostas.push(res.status())
    if (res.status() === 429) break // rate limited
  }

  // Deve ter bloqueado antes de 20 tentativas
  const bloqueado = respostas.includes(429)
  if (bloqueado) {
    const qtdAntesBloqueio = respostas.indexOf(429)
    console.log(`Bloqueado após ${qtdAntesBloqueio} tentativas`)
    expect(qtdAntesBloqueio).toBeLessThan(15) // bloquear antes de 15 tentativas
  } else {
    console.warn('ATENÇÃO: 20 tentativas de login sem bloqueio — vulnerabilidade
brute force')
  }
})

