CREATE OR REPLACE PROCEDURE limpar_dados_teste()
LANGUAGE plpgsql AS $$
BEGIN
  -- Deletar usuários de teste
  DELETE FROM usuarios
  WHERE email LIKE '%@qa.local'
     OR email LIKE '%@teste.com'
     OR nome LIKE 'Usuário Teste%';

  -- Deletar pedidos órfãos
  DELETE FROM pedidos
  WHERE usuario_id NOT IN (SELECT id FROM usuarios);

  RAISE NOTICE 'Limpeza concluída: % usuários removidos', ROW_COUNT;
END;
$$;

-- Executar:
CALL limpar_dados_teste();

